// Public scorecard. Reads the committed evals/results.md (generated by `npm run
// evals`) directly off disk — this page shows exactly what was last committed, not a
// live re-run, so it can't silently drift from what a reviewer can reproduce locally.
import { readFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import type { Metadata } from "next";
import { renderMarkdownLite } from "../components/markdownLite";

export const metadata: Metadata = {
  title: "Evals — Provenance",
  description: "Committed eval scorecard for the Provenance demo.",
};

export default function EvalsPage() {
  const resultsPath = join(process.cwd(), "evals", "results.md");
  const hasResults = existsSync(resultsPath);
  const content = hasResults ? readFileSync(resultsPath, "utf-8") : null;

  return (
    <main>
      <header className="shell" style={{ paddingTop: "56px", paddingBottom: "32px" }}>
        <span className="section-label">
          <i className="dot" aria-hidden="true" />
          Reliability evidence
        </span>
        <h1 className="text-display-lg" style={{ marginTop: "16px" }}>Eval scorecard</h1>
        <p className="text-subtitle-md" style={{ maxWidth: "680px", color: "var(--charcoal)", marginTop: "16px" }}>
          Generated by <code>npm run evals</code> and committed to the repository — this is what actually ran, not
          a summary written after the fact.
        </p>
      </header>

      <section style={{ paddingTop: 0 }}>
        <div className="shell" style={{ maxWidth: "820px" }}>
          {content ? (
            <div style={{ display: "grid", gridTemplateColumns: "minmax(0, 1fr)", gap: "14px" }}>{renderMarkdownLite(content)}</div>
          ) : (
            <p className="text-body-md" style={{ color: "var(--steel)" }}>
              No results yet — run <code>npm run evals</code> to generate <code>evals/results.md</code>.
            </p>
          )}
        </div>
      </section>
    </main>
  );
}
